      "Solve this math problem step by step. Show all your work clearly. " +
      "CRITICAL RULE: Do NOT write << or >> anywhere in your reasoning or intermediate calculations. " +
      "Only at the very last line of your response, write the final symbolic answer in this exact format: " +
      "<<int(expr)>> " +
      "where expr is a single arithmetic expression using only: " +
      "variable names from the problem (no curly braces {}), integers, +, -, *, /, //, %, (, ), int(). " +
      "Always wrap integer results in int(). No LaTeX, no {braces}, no ** operator. " +
      "Keep the expression concise. Example: <<int(n * price - quantity * discount)>>");

  var steps: nat := 0;

  // Phase 0: Close any initially open constrained span
  if insideConstrainedOut && steps < maxSteps {
    var ib: nat := 15;
    if ib > maxSteps - steps { ib := maxSteps - steps; }
    var cg0, ci0, cc0 := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, ib
    );
    generated := cg0;
    insideConstrainedOut := ci0;
    currentConstrainedOut := cc0;
    steps := steps + ib;
  }

  // Phase 1: Free unconstrained generation; intentionally ignore any "<<" emitted
  var pb: nat := (maxSteps * 87) / 100;
  if maxSteps > 0 && pb >= maxSteps { pb := maxSteps - 1; }

  while steps < pb && !insideConstrainedOut
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases pb - steps
