  // CloseSpanWithinBudget tracks the LONGEST complete parse prefix (not the first),
  // preventing early closure at single-variable expressions like "n".
  if insideConstrainedOut && steps < maxSteps {
    var rb: nat := maxSteps - steps;
    var cg3, ci3, cc3 := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, rb
    );
    generated := cg3;
    insideConstrainedOut := ci3;
    currentConstrainedOut := cc3;
    steps := maxSteps;
  }

